program2='''def transform(grid):
    """Join the closest axis-aligned facing edges of neighboring diamonds."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    objects = []
    while remaining:
        seed = remaining.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    q = (r + dr, c + dc)
                    if q in remaining:
                        remaining.remove(q)
                        comp.add(q)
                        stack.append(q)
        objects.append(comp)
    # Pick the closest shared-row or shared-column gap for each pair of objects.
    for i, a in enumerate(objects):
        for b in objects[i+1:]:
            options = []
            for r in {p[0] for p in a} & {p[0] for p in b}:
                aa = sorted(c for rr, c in a if rr == r)
                bb = sorted(c for rr, c in b if rr == r)
                if max(aa) < min(bb):
                    left, right = max(aa), min(bb)
                elif max(bb) < min(aa):
                    left, right = max(bb), min(aa)
                else:
                    continue
                options.append((right-left-1, 'h', r, left, right))
            for c in {p[1] for p in a} & {p[1] for p in b}:
                aa = sorted(r for r, cc in a if cc == c)
                bb = sorted(r for r, cc in b if cc == c)
                if max(aa) < min(bb):
                    top, bottom = max(aa), min(bb)
                elif max(bb) < min(aa):
                    top, bottom = max(bb), min(aa)
                else:
                    continue
                options.append((bottom-top-1, 'v', c, top, bottom))
            if not options:
                continue
            gap, direction, fixed, start, end = min(options)
            if gap <= 0:
                continue
            # A third object between these two blocks the connection.
            blocked = False
            for other in objects:
                if other is a or other is b:
                    continue
                if direction == 'h' and any(r == fixed and start < c < end for r, c in other):
                    blocked = True
                if direction == 'v' and any(c == fixed and start < r < end for r, c in other):
                    blocked = True
            if blocked:
                continue
            for x in range(start+1, end):
                if direction == 'h' and out[fixed][x] == 0:
                    out[fixed][x] = 1
                elif direction == 'v' and out[x][fixed] == 0:
                    out[x][fixed] = 1
    return out
'''
